+Array OpenXRSpatialContainerExtension::get_supported_bounds_modes() {
+	Array modes;
+
+	if (spatial_container_properties.supportsBounded) {
+		modes.push_back(OpenXRSpatialContainerState::BOUNDS_MODE_BOUNDED);
